CREATE TABLE IF NOT EXISTS cohorts (cohort_id INTEGER PRIMARY KEY AUTOINCREMENT, code VARCHAR(40) NOT NULL UNIQUE, name VARCHAR(150) NOT NULL, admission_year INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS user_security (user_id INTEGER PRIMARY KEY, must_change_password INTEGER NOT NULL DEFAULT 0, password_version INTEGER NOT NULL DEFAULT 1, FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS sessions (token_hash VARCHAR(64) PRIMARY KEY, user_id INTEGER NOT NULL, csrf_token VARCHAR(64) NOT NULL, expires_at VARCHAR(40) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS app_lock (lock_id INTEGER PRIMARY KEY, revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS charges (charge_id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL, name VARCHAR(200) NOT NULL, amount DECIMAL(15,0) NOT NULL CHECK(amount>0), due_date DATE NOT NULL, created_by INTEGER NOT NULL, FOREIGN KEY(student_id) REFERENCES students(student_id), FOREIGN KEY(created_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS receipts (receipt_id INTEGER PRIMARY KEY AUTOINCREMENT, receipt_code VARCHAR(50) NOT NULL UNIQUE, charge_id INTEGER NOT NULL, amount DECIMAL(15,0) NOT NULL CHECK(amount>0), method VARCHAR(30) NOT NULL, received_at VARCHAR(40) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'active', reason TEXT, recorded_by INTEGER NOT NULL, FOREIGN KEY(charge_id) REFERENCES charges(charge_id), FOREIGN KEY(recorded_by) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS ai_conversations (conversation_id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INTEGER NOT NULL, title VARCHAR(150) NOT NULL, context_json TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(user_id) REFERENCES users(user_id));
CREATE TABLE IF NOT EXISTS ai_messages (message_id INTEGER PRIMARY KEY AUTOINCREMENT, conversation_id INTEGER NOT NULL, role VARCHAR(20) NOT NULL, content_json TEXT NOT NULL, created_at VARCHAR(40) NOT NULL, FOREIGN KEY(conversation_id) REFERENCES ai_conversations(conversation_id));
